const j = $input.first().json;
const wfName = j.workflow?.name ?? 'unknown';
const msg = j.execution?.error?.message ?? String(j.execution?.error ?? 'Error');
const now = new Date().toISOString();
return [
  {
    json: {
      run_id: `run_${wfName}_error_${Date.now()}`,
      run_started: now,
      run_finished: now,
      job_name: wfName,
      rows_added: 0,
      rows_updated: 0,
      status: 'error',
      error_log: msg,
      sources_summary_json: null,
      stage_log_root_id: null,
    },
  },
];

const run_id = 'run_wf_collect_trends_' + Date.now();
const run_started = new Date().toISOString();
return [
  {
    json: {
      run_id,
      run_started,
      market: 'UK',
      category: 'all',
      parallel_dispatch: ['google_trends', 'etsy_autocomplete', 'pinterest_trends'],
    },
  },
];

const input = $input.first().json;
const inputMarket = input.market ?? 'UK';
const geo = inputMarket === 'UK' ? 'GB' : String(inputMarket).toUpperCase();
const hl = geo === 'GB' ? 'en-GB' : 'en-US';
const outMarketLabel = geo === 'GB' ? 'UK' : geo;
const helpers = this.helpers;

function slugify(text) {
  return String(text)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '_')
    .replace(/^_+|_+$/g, '')
    .slice(0, 80);
}

function decodeXmlEntities(text) {
  return String(text || '')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&apos;/g, "'");
}

function stripTags(text) {
  return decodeXmlEntities(String(text || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim());
}

function extractTraffic(block) {
  const m = String(block).match(/<ht:approx_traffic>([\s\S]*?)<\/ht:approx_traffic>/i);
  return m ? stripTags(m[1]) : '';
}

function extractTitle(block) {
  const m = String(block).match(/<title>([\s\S]*?)<\/title>/i);
  return m ? stripTags(m[1]) : '';
}

function extractRelated(block) {
  const related = [];
  const matches = String(block).matchAll(/<a[^>]*>([\s\S]*?)<\/a>/gi);
  for (const match of matches) {
    const text = stripTags(match[1]);
    if (text) related.push(text);
  }
  return related;
}

function buildRow(title, related, traffic) {
  const slug = slugify(title) || 'unknown';
  return {
    json: {
      signal_id: 'sig_google_' + new Date().toISOString().slice(0, 10) + '_' + slug,
      date_collected: new Date().toISOString(),
      source: 'google_trends',
      market: outMarketLabel,
      term: title,
      related_term: (Array.isArray(related) ? related : []).slice(0, 5).join(' | '),
      category: 'general',
      signal_type: 'rising_query',
      velocity_hint: traffic || 'medium',
      url: 'https://trends.google.com/trending?geo=' + encodeURIComponent(geo),
      raw_payload_json: JSON.stringify({ title, related, traffic }),
    },
  };
}

const baseHeaders = {
  Accept: 'application/rss+xml, text/xml, */*',
  'Accept-Language': hl + ',en;q=0.8',
  'User-Agent': 'Mozilla/5.0 (compatible; n8n-trends-bot/1.0; +https://example.invalid)',
};

async function fetchRss() {
  const url = 'https://trends.google.com/trending/rss?geo=' + encodeURIComponent(geo) + '&safe=active';
  const bodyText = await helpers.httpRequest({
    method: 'GET',
    url,
    headers: baseHeaders,
    returnFullResponse: false,
    json: false,
  });
  const xml = String(bodyText || '');
  const itemBlocks = xml.match(/<item>[\s\S]*?<\/item>/gi) || [];
  return itemBlocks
    .slice(0, 20)
    .map((block) => {
      const title = extractTitle(block);
      const related = extractRelated(block);
      const traffic = extractTraffic(block);
      return buildRow(title, related, traffic);
    })
    .filter((r) => r.json.term);
}

async function fetchDailytrendsJson() {
  const url =
    'https://trends.google.com/trends/api/dailytrends?hl=' +
    encodeURIComponent(hl) +
    '&tz=0&geo=' +
    encodeURIComponent(geo) +
    '&ns=15';
  const bodyText = await helpers.httpRequest({
    method: 'GET',
    url,
    headers: { ...baseHeaders, Accept: 'application/json, text/plain, */*' },
    returnFullResponse: false,
    json: false,
  });
  let text = String(bodyText || '');
  text = text.replace(/^\)\]\}',?\s*/, '');
  let data;
  try {
    data = JSON.parse(text);
  } catch (_pe) {
    return [];
  }
  const days = (data && data.default && data.default.trendingSearchesDays) || [];
  const rows = [];
  for (const day of days) {
    const trends = Array.isArray(day && day.trendingSearches) ? day.trendingSearches : [];
    for (const t of trends) {
      const title = String((t && t.title && t.title.query) || '').trim();
      if (!title) continue;
      const related = (Array.isArray(t && t.relatedQueries) ? t.relatedQueries : [])
        .map((r) => String((r && r.query) || ''))
        .filter(Boolean);
      const traffic = String((t && t.formattedTraffic) || '').trim();
      rows.push(buildRow(title, related, traffic));
    }
  }
  return rows;
}

try {
  let rows = [];
  try {
    rows = await fetchRss();
  } catch (_e1) {
    rows = [];
  }
  if (!rows.length) {
    try {
      rows = await fetchDailytrendsJson();
    } catch (_e2) {
      rows = [];
    }
  }
  return rows;
} catch (err) {
  const msg = (err && err.message) || String(err);
  return [
    {
      json: {
        signal_id: 'ERROR',
        source: 'google_trends',
        term: 'fetch_failed',
        date_collected: new Date().toISOString(),
        raw_payload_json: msg,
      },
    },
  ];
}

const SEEDS = [
  'pickleball','stanley cup','cottagecore','dark academia','granola girl',
  'coastal grandmother','that girl','mob wife','quiet luxury','coquette',
];
const dateStamp = new Date().toISOString().slice(0, 10);
const dateCollected = new Date().toISOString();
const helpers = this.helpers;

function slugify(text) {
  return String(text).toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 80);
}
function dedupeKey(p) { return String(p).trim().toLowerCase(); }
function delay(ms) { return new Promise((r) => setTimeout(r, ms)); }

function extractPhrases(payload) {
  if (!payload) return [];
  if (Array.isArray(payload)) {
    return payload
      .map((x) =>
        typeof x === 'string'
          ? x
          : (x && (x.query ?? x.title ?? x.text ?? x.value ?? x.suggestion ?? x.name ?? x.phrase)) || ''
      )
      .filter(Boolean);
  }
  if (typeof payload !== 'object') return [];
  const buckets = [
    payload.results,
    payload.suggestions,
    payload.data,
    payload.prefixes,
    payload.autocomplete,
    payload.items,
    payload.related,
  ].filter(Array.isArray);
  for (const arr of buckets) {
    const out = extractPhrases(arr);
    if (out.length) return out;
  }
  return [];
}

const UAS = [
  'Mozilla/5.0 (Macintosh; Intel Mac OS X 14_4) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36',
  'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36',
  'Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36',
];
function pickUA() { return UAS[Math.floor(Math.random() * UAS.length)]; }

async function tryFetch(url, jsonExpected, extraHeaders) {
  const headers = {
    Accept: 'application/json, text/plain, */*',
    'Accept-Language': 'en-GB,en;q=0.8',
    Referer: 'https://www.etsy.com/',
    'User-Agent': pickUA(),
    ...(extraHeaders || {}),
  };
  const res = await helpers.httpRequest({ method: 'GET', url, headers, json: jsonExpected });
  return res;
}

async function fetchSuggestions(seed) {
  // Primary Etsy API endpoint.
  try {
    const url = 'https://www.etsy.com/api/v3/ajax/autocomplete/prefix?q=' + encodeURIComponent(seed) + '&limit=10';
    const res = await tryFetch(url, true);
    const phrases = extractPhrases(res);
    if (phrases.length) return { phrases, via: 'etsy_v3_prefix' };
  } catch (_e1) {}

  // Secondary Etsy endpoint.
  try {
    const url2 = 'https://www.etsy.com/suggestions_ajax.php?search_query=' + encodeURIComponent(seed);
    const raw = await tryFetch(url2, false);
    let body = raw;
    if (typeof body === 'string') {
      try { body = JSON.parse(body); } catch (_pe) { body = null; }
    }
    const phrases = extractPhrases(body);
    if (phrases.length) return { phrases, via: 'etsy_suggestions_ajax' };
  } catch (_e2) {}

  // Reliability fallback: DuckDuckGo autocomplete (public, no key).
  try {
    const url3 = 'https://duckduckgo.com/ac/?q=' + encodeURIComponent(seed) + '&type=list';
    const res3 = await tryFetch(url3, true, { Referer: 'https://duckduckgo.com/' });
    const phrases = extractPhrases(res3);
    if (phrases.length) return { phrases, via: 'duckduckgo_ac_fallback' };
  } catch (_e3) {}

  return { phrases: null, via: 'none' };
}

const seen = new Map();
const out = [];

for (let i = 0; i < SEEDS.length; i++) {
  if (i > 0) await delay(500);
  const seedTerm = SEEDS[i];
  const result = await fetchSuggestions(seedTerm);
  const phrases = result.phrases;

  if (phrases === null) {
    out.push({
      json: {
        signal_id: 'ERROR',
        source: 'etsy_autocomplete',
        term: 'fetch_failed',
        date_collected: dateCollected,
        related_term: seedTerm,
        raw_payload_json: JSON.stringify({ seed: seedTerm, error: 'all endpoints failed', via: result.via }),
      },
    });
    continue;
  }

  for (const phrase of phrases) {
    const key = dedupeKey(phrase);
    if (!key || seen.has(key)) continue;
    seen.set(key, true);
    const slug = slugify(phrase) || 'unknown';
    out.push({
      json: {
        signal_id: 'sig_etsy_' + dateStamp + '_' + slug,
        date_collected: dateCollected,
        source: 'etsy_autocomplete',
        market: 'UK',
        term: phrase,
        related_term: seedTerm,
        category: 'marketplace_phrase',
        signal_type: 'buyer_intent',
        velocity_hint: result.via === 'duckduckgo_ac_fallback' ? 'fallback' : 'unknown',
        url: 'https://www.etsy.com/search?q=' + encodeURIComponent(phrase),
        raw_payload_json: JSON.stringify({ seed: seedTerm, suggestion: phrase, via: result.via }),
      },
    });
  }
}

return out;

const SEEDS = [
  'pickleball','stanley cup','cottagecore','dark academia','granola girl',
  'coastal grandmother','that girl','mob wife','quiet luxury','coquette',
];
const dateStamp = new Date().toISOString().slice(0, 10);
const dateCollected = new Date().toISOString();
const helpers = this.helpers;

function slugify(text) {
  return String(text).toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 80);
}
function dedupeKey(p) { return String(p).trim().toLowerCase(); }
function delay(ms) { return new Promise((r) => setTimeout(r, ms)); }

function isLikelySuggestion(v) {
  const s = String(v || '').trim();
  if (!s || s.length < 3 || s.length > 60) return false;
  if (/[:{}<>]/.test(s)) return false;
  if (/\b(middleware|responder|resource|provider|wrapper|request|parser|loader|cookieparser|sessionparser|csrfrequest)\b/i.test(s)) return false;
  if (/^[a-z]+(?:[A-Z][a-z0-9]+)+$/.test(s)) return false;
  if (/^[^\s]+$/.test(s) && /[A-Z]/.test(s)) return false;
  return true;
}

function collectFromArray(arr) {
  return (Array.isArray(arr) ? arr : [])
    .map((x) => typeof x === 'string' ? x : (x && (x.display_name ?? x.query ?? x.term ?? x.phrase ?? x.suggestion ?? x.name)) || '')
    .map((x) => String(x || '').replace(/\u([0-9a-fA-F]{4})/g, (_, h) => String.fromCharCode(parseInt(h, 16))).trim())
    .filter(isLikelySuggestion);
}

function extractPhrases(payload) {
  if (!payload || typeof payload !== 'object') return [];
  const rr = payload.resource_response || {};
  const primary = collectFromArray(rr.data);
  if (primary.length) return primary;
  const fallbackBuckets = [payload.results, payload.suggestions, payload.terms, payload.items, payload.recommended_terms, payload.data];
  for (const b of fallbackBuckets) {
    const out = collectFromArray(b);
    if (out.length) return out;
  }
  return [];
}

function extractPhrasesFromHtml(html) {
  const text = String(html || '');
  const out = [];
  const patterns = [
    /"display_name"\s*:\s*"([^"]+)"/g,
    /"name"\s*:\s*"([^"]+)"/g,
    /"query"\s*:\s*"([^"]+)"/g,
  ];
  for (const re of patterns) {
    let m;
    while ((m = re.exec(text)) !== null) {
      const v = String(m[1] || '').replace(/\u([0-9a-fA-F]{4})/g, (_, h) => String.fromCharCode(parseInt(h, 16)));
      if (isLikelySuggestion(v)) out.push(v);
    }
  }
  return out;
}

const UA =
  'Mozilla/5.0 (Macintosh; Intel Mac OS X 14_4) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36';

async function fetchTypeahead(seed) {
  const headers = {
    Accept: 'application/json, text/javascript, */*; q=0.01',
    'Accept-Language': 'en-GB,en;q=0.8',
    Referer: 'https://www.pinterest.com/',
    'User-Agent': UA,
    'X-Requested-With': 'XMLHttpRequest',
  };

  // Primary endpoint + JSON parser.
  try {
    const data = encodeURIComponent(JSON.stringify({ options: { pin_scope: 'pins', term: seed }, context: {} }));
    const url = 'https://www.pinterest.com/resource/UserSearchTypeaheadResource/get/?source_url=%2Fideas%2F&data=' + data + '&_=' + Date.now();
    const res = await helpers.httpRequest({ method: 'GET', url, headers, json: true });
    const phrases = extractPhrases(res);
    if (phrases.length) return { phrases, via: 'pinterest_typeahead_json' };
  } catch (_e1) {}

  // Secondary endpoint/parser path: HTML autocomplete page + regex extraction.
  try {
    const url2 = 'https://www.pinterest.com/search/autocomplete/?q=' + encodeURIComponent(seed);
    const html = await helpers.httpRequest({ method: 'GET', url: url2, headers: { ...headers, Accept: 'text/html, */*; q=0.1' }, json: false });
    const phrases = extractPhrasesFromHtml(html);
    if (phrases.length) return { phrases, via: 'pinterest_autocomplete_html' };
  } catch (_e2) {}

  // Reliability fallback: DuckDuckGo autocomplete (public, no key).
  try {
    const url3 = 'https://duckduckgo.com/ac/?q=' + encodeURIComponent(seed) + '&type=list';
    const ddg = await helpers.httpRequest({
      method: 'GET',
      url: url3,
      headers: { Accept: 'application/json, text/plain, */*', Referer: 'https://duckduckgo.com/', 'User-Agent': UA },
      json: true,
    });
    const phrases = extractPhrases(ddg);
    if (phrases.length) return { phrases, via: 'duckduckgo_ac_fallback' };
  } catch (_e3) {}

  return { phrases: null, via: 'none' };
}

const seen = new Map();
const out = [];

for (let i = 0; i < SEEDS.length; i++) {
  if (i > 0) await delay(500);
  const seed = SEEDS[i];
  const result = await fetchTypeahead(seed);
  const phrases = result.phrases;

  if (phrases === null) {
    out.push({
      json: {
        signal_id: 'ERROR',
        source: 'pinterest_trends',
        term: 'fetch_failed',
        date_collected: dateCollected,
        related_term: seed,
        raw_payload_json: JSON.stringify({ seed, error: 'pinterest endpoints failed', via: result.via }),
      },
    });
    continue;
  }

  for (const phrase of phrases) {
    if (!isLikelySuggestion(phrase)) continue;
    const key = dedupeKey(phrase);
    if (!key || seen.has(key)) continue;
    seen.set(key, true);
    const slug = slugify(phrase) || 'unknown';
    out.push({
      json: {
        signal_id: 'sig_pinterest_' + dateStamp + '_' + slug,
        date_collected: dateCollected,
        source: 'pinterest_trends',
        market: 'UK',
        term: phrase,
        related_term: seed,
        category: 'visual_inspiration',
        signal_type: 'audience_interest',
        velocity_hint: result.via === 'duckduckgo_ac_fallback' ? 'fallback' : 'unknown',
        url: 'https://www.pinterest.com/search/pins/?q=' + encodeURIComponent(phrase),
        raw_payload_json: JSON.stringify({ seed, suggestion: phrase, via: result.via }),
      },
    });
  }
}

return out;

const items = $input.all();
const seen = new Set();
const out = [];
for (let i = 0; i < items.length; i++) {
  const json = items[i].json || {};
  const id = json.signal_id;
  if (!id) continue;
  // Preserve per-branch diagnostic sentinel rows instead of collapsing all ERROR rows.
  const key = id === 'ERROR'
    ? ['ERROR', String(json.source || ''), String(json.related_term || ''), String(i)].join('::')
    : String(id);
  if (seen.has(key)) continue;
  seen.add(key);
  out.push({ json });
}
return out;

// Stage 1 row-contract validator (Item 2 of pipeline hardening plan).
// Inlined from sourceContractValidator.js.

const REQUIRED = ['signal_id', 'source', 'term', 'date_collected', 'raw_payload_json'];
const OPTIONAL = ['market', 'related_term', 'category', 'signal_type', 'velocity_hint', 'url'];

function validateRow(row) {
  const reasons = [];
  if (!row || typeof row !== 'object') return { ok: false, reasons: ['row_not_object'] };
  const out = {};
  for (const f of REQUIRED) {
    const v = row[f];
    if (v == null || String(v).trim() === '') { reasons.push('missing:' + f); continue; }
    out[f] = String(v).trim();
  }
  if (out.signal_id === 'ERROR' || (out.term && out.term.toLowerCase() === 'fetch_failed')) {
    return { ok: false, reasons: ['sentinel_error_row'] };
  }
  if (out.date_collected) {
    const ts = Date.parse(out.date_collected);
    if (!Number.isFinite(ts)) reasons.push('invalid:date_collected');
  }
  if (out.raw_payload_json) {
    try { JSON.parse(out.raw_payload_json); } catch (_e) {
      if (String(out.raw_payload_json).length > 4000) reasons.push('invalid:raw_payload_json_too_long');
    }
  }
  for (const f of OPTIONAL) if (row[f] != null) out[f] = String(row[f]).trim();
  if (out.term && out.term.length > 200) reasons.push('invalid:term_too_long');
  if (out.signal_id && out.signal_id.length > 200) reasons.push('invalid:signal_id_too_long');
  return { ok: reasons.length === 0, reasons, normalized: out };
}

const items = $input.all();
const accepted = [];
const rejected = [];
const bySource = {};
const reasonsSummary = {};

for (const it of items) {
  const raw = it.json || {};
  const src = String(raw.source || 'unknown').trim() || 'unknown';
  if (!bySource[src]) bySource[src] = { accepted: 0, rejected: 0, last_reason: '' };
  const res = validateRow(raw);
  if (res.ok) {
    accepted.push({ json: res.normalized });
    bySource[src].accepted += 1;
  } else {
    rejected.push({ json: { __rejected: true, raw, reasons: res.reasons } });
    bySource[src].rejected += 1;
    bySource[src].last_reason = res.reasons.join(',');
    for (const r of res.reasons) reasonsSummary[r] = (reasonsSummary[r] || 0) + 1;
  }
}

const meta = $('Set Run Metadata').first().json;
const summary = {
  json: {
    __summary: true,
    run_id: meta.run_id,
    run_started: meta.run_started,
    accepted_count: accepted.length,
    rejected_count: rejected.length,
    reasons_summary: reasonsSummary,
    by_source: bySource,
  },
};

return accepted.length ? accepted.concat([summary]) : [summary];

// Filter out the validator's summary item before sheet append.
const rows = $input.all().filter((it) => !it.json || !it.json.__summary);
return rows;

// Build source_health rows from validator summary.
const meta = $('Set Run Metadata').first().json;
const summaries = $('Validate raw_signals contract').all().filter((it) => it.json && it.json.__summary);
const summary = summaries.length ? summaries[summaries.length - 1].json : { by_source: {} };
const bySource = summary.by_source || {};
const expectedSources = Array.isArray(meta.parallel_dispatch) ? meta.parallel_dispatch : [];
const runDate = (meta.run_started || new Date().toISOString()).slice(0, 10);
const out = [];

function pushHealth(sourceName, e, fallbackReason) {
  const accepted = Number((e && e.accepted) || 0);
  const rejected = Number((e && e.rejected) || 0);
  const total = accepted + rejected;
  let status = 'ok';
  if (total === 0) status = 'error';
  else if (rejected > 0 && rejected === total) status = 'error';
  else if (rejected > 0) status = 'degraded';
  out.push({
    json: {
      health_id: 'health_' + sourceName + '_' + runDate + '_' + Date.now() + '_' + Math.floor(Math.random() * 1e6),
      run_id: meta.run_id,
      run_date: runDate,
      source_name: sourceName,
      status,
      rows_in: total,
      rows_valid: accepted,
      rows_rejected: rejected,
      duration_ms: 0,
      last_error: ((e && e.last_reason) || fallbackReason || ''),
      http_status_codes: '',
      consecutive_failures: 0,
      updated_at: new Date().toISOString(),
    },
  });
}

// First: sources present in validator summary.
for (const sourceName of Object.keys(bySource)) {
  pushHealth(sourceName, bySource[sourceName], '');
}

// Then: expected sources that produced no contract-evaluable rows.
for (const sourceName of expectedSources) {
  if (Object.prototype.hasOwnProperty.call(bySource, sourceName)) continue;
  pushHealth(sourceName, { accepted: 0, rejected: 0, last_reason: 'no_rows_after_validation' }, 'no_rows_after_validation');
}

return out.length ? out : [{
  json: {
    health_id: 'health_unknown_' + runDate + '_' + Date.now(),
    run_id: meta.run_id,
    run_date: runDate,
    source_name: 'unknown',
    status: 'error',
    rows_in: 0,
    rows_valid: 0,
    rows_rejected: 0,
    duration_ms: 0,
    last_error: 'summary_missing',
    http_status_codes: '',
    consecutive_failures: 0,
    updated_at: new Date().toISOString(),
  },
}];

// Build stage_run_logs envelope rows for this workflow.
const meta = $('Set Run Metadata').first().json;
const rowsIn = $('Deduplicate signals').all().length;
const rowsOut = $('Filter validated rows').all().length;
const summaryItem = $('Validate raw_signals contract').all().filter((it) => it.json && it.json.__summary);
const summary = summaryItem.length ? summaryItem[summaryItem.length - 1].json : { rejected_count: 0 };
const rejected = summary.rejected_count || 0;
const startedAt = meta.run_started || new Date().toISOString();
const endedAt = new Date().toISOString();
const durationMs = Math.max(0, Date.parse(endedAt) - Date.parse(startedAt));
const status = rejected === rowsIn && rowsIn > 0 ? 'error' : (rejected > 0 ? 'warn' : 'success');
return [
  {
    json: {
      log_id: 'slog_wf_collect_trends_collect_' + Date.now() + '_start',
      run_id: meta.run_id,
      workflow_name: 'wf_collect_trends',
      stage_name: 'collect_and_append',
      event_type: 'start',
      started_at: startedAt,
      ended_at: null,
      duration_ms: 0,
      rows_in: rowsIn,
      rows_out: 0,
      error_count: 0,
      status: 'running',
      error_summary: '',
      attempt_number: 1,
      parent_log_id: '',
      metadata_json: null,
    },
  },
  {
    json: {
      log_id: 'slog_wf_collect_trends_collect_' + Date.now() + '_end',
      run_id: meta.run_id,
      workflow_name: 'wf_collect_trends',
      stage_name: 'collect_and_append',
      event_type: status === 'error' ? 'error' : 'end',
      started_at: startedAt,
      ended_at: endedAt,
      duration_ms: durationMs,
      rows_in: rowsIn,
      rows_out: rowsOut,
      error_count: rejected,
      status,
      error_summary: rejected ? ('rejected_' + rejected + '_rows') : '',
      attempt_number: 1,
      parent_log_id: '',
      metadata_json: JSON.stringify({ reasons_summary: summary.reasons_summary || {} }),
    },
  },
];

const meta = $('Set Run Metadata').first().json;
const rows_added = $('Filter validated rows').all().length;
const summaries = $('Validate raw_signals contract').all().filter((it) => it.json && it.json.__summary);
const summary = summaries.length ? summaries[summaries.length - 1].json : { rejected_count: 0, by_source: {} };
const run_finished = new Date().toISOString();
return [
  {
    json: {
      run_id: meta.run_id,
      run_started: meta.run_started,
      run_finished,
      job_name: 'wf_collect_trends',
      rows_added,
      rows_updated: 0,
      status: summary.rejected_count > 0 ? 'success_with_rejects' : 'success',
      error_log: summary.rejected_count > 0 ? ('rejects=' + summary.rejected_count) : '',
      sources_summary_json: (summary.by_source || {}),
      stage_log_root_id: null,
    },
  },
];
